// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address logger, bool status) public {
        vm.assume(caller != address(0));
        vm.assume(logger != address(0));
        vm.assume(caller != logger);

        // Pre-state: only owner can call setApprovedLogger
        // The owner is the address that deployed the contract (address(this))
        bool ownerIsCaller = (caller == address(this));

        // Attempt to set a logger
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.setApprovedLogger.selector, logger, status));

        // The rule: setApprovedLogger should only succeed if caller is owner
        // In the correct contract (C), only owner can call setApprovedLogger
        // In the buggy version, only non-owner can call it
        assertTrue(success == ownerIsCaller, "setApprovedLogger should only be callable by owner");
    }
}

